-- V2.4.0：帮助中心数据化、搜索与后台逐条管理。
-- 前置版本：2.2.9；MySQL 5.7.44；V2.4.0 预发布阶段直接重建帮助中心预览表。
SET NAMES utf8mb4;

-- 2026-09-28：施工订单支持“多师傅报价 / 单师傅抢单”两种接单方式。
-- V2.4.0 尚未正式发布，但开发库可能已执行过本文件，因此这里仍按 MySQL 5.7 可重复执行方式补列。
SET @v240_dispatch_mode_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='dispatch_mode'
);
SET @v240_dispatch_mode_ddl := IF(
  @v240_dispatch_mode_exists > 0,
  'SELECT 1',
  'ALTER TABLE `orders` ADD COLUMN `dispatch_mode` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT ''multi_quote'' COMMENT ''施工接单方式：multi_quote多师傅报价、single_grab单师傅抢单'' AFTER `workflow_profile`'
);
PREPARE v240_dispatch_mode_stmt FROM @v240_dispatch_mode_ddl;
EXECUTE v240_dispatch_mode_stmt;
DEALLOCATE PREPARE v240_dispatch_mode_stmt;
UPDATE `orders` SET `dispatch_mode`='multi_quote' WHERE `dispatch_mode` IS NULL OR `dispatch_mode` NOT IN ('multi_quote','single_grab');
INSERT INTO `database_field_dictionary` (`table_name`,`field_name`,`chinese_name`,`description`,`created_at`,`updated_at`)
SELECT 'orders','dispatch_mode','接单方式','multi_quote=多师傅报价；single_grab=单师傅抢单，抢单后先联系用户再报价',UTC_TIMESTAMP(),UTC_TIMESTAMP()
WHERE NOT EXISTS (
  SELECT 1 FROM `database_field_dictionary` WHERE `table_name`='orders' AND `field_name`='dispatch_mode'
);


-- 2026-09-29：期望费用支持“总价金额 / 单价文本”；仅总价可在 single_grab 抢单时直接成交，单价绝不参与金额计算。
-- 2.4.0 尚未正式发布，但开发库可能已执行过旧“预期价格”草稿，因此只做一次干净改名，不长期保留旧字段。
SET @v240_old_expected_price_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_price_cents'
);
SET @v240_expected_fee_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_fee_cents'
);
SET @v240_expected_fee_rename := IF(
  @v240_old_expected_price_exists > 0 AND @v240_expected_fee_exists = 0,
  'ALTER TABLE `orders` CHANGE COLUMN `expected_price_cents` `expected_fee_cents` bigint unsigned NULL COMMENT ''用户下单期望总价金额（分）；仅total使用并可在single_grab中直接成交''',
  'SELECT 1'
);
PREPARE v240_expected_fee_rename_stmt FROM @v240_expected_fee_rename;
EXECUTE v240_expected_fee_rename_stmt;
DEALLOCATE PREPARE v240_expected_fee_rename_stmt;

SET @v240_expected_fee_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_fee_cents'
);
SET @v240_expected_fee_add := IF(
  @v240_expected_fee_exists > 0,
  'SELECT 1',
  'ALTER TABLE `orders` ADD COLUMN `expected_fee_cents` bigint unsigned NULL COMMENT ''用户下单期望总价金额（分）；仅total使用并可在single_grab中直接成交'' AFTER `dispatch_mode`'
);
PREPARE v240_expected_fee_add_stmt FROM @v240_expected_fee_add;
EXECUTE v240_expected_fee_add_stmt;
DEALLOCATE PREPARE v240_expected_fee_add_stmt;

SET @v240_expected_fee_text_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_fee_text'
);
SET @v240_expected_fee_text_add := IF(
  @v240_expected_fee_text_exists > 0,
  'SELECT 1',
  'ALTER TABLE `orders` ADD COLUMN `expected_fee_text` varchar(500) COLLATE utf8mb4_unicode_ci NULL COMMENT ''用户填写的期望单价说明文本；仅unit使用，不参与金额计算'' AFTER `expected_fee_cents`'
);
PREPARE v240_expected_fee_text_add_stmt FROM @v240_expected_fee_text_add;
EXECUTE v240_expected_fee_text_add_stmt;
DEALLOCATE PREPARE v240_expected_fee_text_add_stmt;

-- 若开发库曾部分执行过新旧两版草稿，先把旧值补到新列，再彻底删除旧列。
SET @v240_old_expected_price_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_price_cents'
);
SET @v240_expected_fee_merge := IF(
  @v240_old_expected_price_exists > 0,
  'UPDATE `orders` SET `expected_fee_cents`=COALESCE(`expected_fee_cents`,`expected_price_cents`)',
  'SELECT 1'
);
PREPARE v240_expected_fee_merge_stmt FROM @v240_expected_fee_merge;
EXECUTE v240_expected_fee_merge_stmt;
DEALLOCATE PREPARE v240_expected_fee_merge_stmt;
SET @v240_expected_fee_drop_old := IF(
  @v240_old_expected_price_exists > 0,
  'ALTER TABLE `orders` DROP COLUMN `expected_price_cents`',
  'SELECT 1'
);
PREPARE v240_expected_fee_drop_old_stmt FROM @v240_expected_fee_drop_old;
EXECUTE v240_expected_fee_drop_old_stmt;
DEALLOCATE PREPARE v240_expected_fee_drop_old_stmt;

SET @v240_expected_fee_type_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='orders' AND COLUMN_NAME='expected_fee_type'
);
SET @v240_expected_fee_type_add := IF(
  @v240_expected_fee_type_exists > 0,
  'SELECT 1',
  'ALTER TABLE `orders` ADD COLUMN `expected_fee_type` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT ''期望费用计价方式：total总价、unit单价'' AFTER `dispatch_mode`'
);
PREPARE v240_expected_fee_type_add_stmt FROM @v240_expected_fee_type_add;
EXECUTE v240_expected_fee_type_add_stmt;
DEALLOCATE PREPARE v240_expected_fee_type_add_stmt;

UPDATE `orders`
SET `expected_fee_type`=CASE WHEN `expected_fee_cents` IS NULL THEN NULL ELSE 'total' END
WHERE `expected_fee_type` IS NULL OR `expected_fee_type` NOT IN ('total','unit');

-- 2.4.0 仍处开发期：此前试做的“单价金额”转换成只读文本后清空 cents，彻底断开金额语义。
UPDATE `orders`
SET `expected_fee_text`=COALESCE(NULLIF(TRIM(`expected_fee_text`),''),CONCAT('原单价 ',TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM CAST(CAST(`expected_fee_cents`/100 AS DECIMAL(18,2)) AS CHAR))),'元'))
WHERE `expected_fee_type`='unit' AND `expected_fee_cents` IS NOT NULL;
UPDATE `orders` SET `expected_fee_cents`=NULL WHERE `expected_fee_type`='unit';

DELETE FROM `database_field_dictionary`
WHERE `table_name`='orders' AND `field_name` IN ('expected_price_cents','expected_fee_type','expected_fee_cents','expected_fee_text');
INSERT INTO `database_field_dictionary` (`table_name`,`field_name`,`chinese_name`,`description`,`created_at`,`updated_at`) VALUES
('orders','expected_fee_type','期望费用计价方式','total=总价金额；unit=单价文本。仅total参与single_grab直接成交',UTC_TIMESTAMP(),UTC_TIMESTAMP()),
('orders','expected_fee_cents','期望总价（分）','仅total使用；用户期望总价可用于single_grab直接成交',UTC_TIMESTAMP(),UTC_TIMESTAMP()),
('orders','expected_fee_text','期望单价说明','仅unit使用；可按材料分别填写不同单位，纯文本展示，不参与任何金额计算',UTC_TIMESTAMP(),UTC_TIMESTAMP());

-- 2026-09-29：尚未正式运营，order_submit 不保留开发期 V2 草稿；本版直接修改已发布 V1 配置。
-- 删除 V2+ 草稿会由外键级联清理其步骤、字段、选项和规则；V1 继续作为小程序实际读取的唯一已发布版本。
DELETE v FROM `form_schema_versions` v
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
WHERE fs.`schema_key`='order_submit' AND v.`version_no`>1 AND v.`status`='draft';

UPDATE `form_schema_versions` v
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
SET v.`status`='published'
WHERE fs.`schema_key`='order_submit' AND v.`version_no`=1;

UPDATE `form_schemas` fs
INNER JOIN `form_schema_versions` v1 ON v1.`schema_id`=fs.`id` AND v1.`version_no`=1
SET fs.`current_version`=1,fs.`status`='published',fs.`updated_at`=UTC_TIMESTAMP()
WHERE fs.`schema_key`='order_submit';

DELETE r FROM `form_rules` r
INNER JOIN `form_schema_versions` v ON v.`id`=r.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
WHERE fs.`schema_key`='order_submit' AND r.`rule_key` IN ('v240_measure_hide_expected_price','v240_measure_hide_expected_fee');

DELETE oldf FROM `form_fields` oldf
INNER JOIN `form_steps` s ON s.`id`=oldf.`step_id`
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
INNER JOIN `form_fields` nf ON nf.`step_id`=oldf.`step_id` AND nf.`field_key`='expected_fee'
WHERE fs.`schema_key`='order_submit' AND oldf.`field_key`='expected_price';

UPDATE `form_fields` f
INNER JOIN `form_steps` s ON s.`id`=f.`step_id`
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
LEFT JOIN `form_fields` nf ON nf.`step_id`=f.`step_id` AND nf.`field_key`='expected_fee'
SET f.`field_key`='expected_fee',f.`updated_at`=UTC_TIMESTAMP()
WHERE fs.`schema_key`='order_submit' AND f.`field_key`='expected_price' AND nf.`id` IS NULL;

DELETE f FROM `form_fields` f
INNER JOIN `form_steps` s ON s.`id`=f.`step_id`
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
WHERE fs.`schema_key`='order_submit' AND f.`field_key`='expected_fee' AND s.`step_key`<>'product_info';

INSERT INTO `form_fields`
(`step_id`,`field_key`,`label`,`component_type`,`data_type`,`placeholder`,`help_text`,`is_required`,`default_value_json`,`validation_json`,`ui_config_json`,`sort_order`,`status`,`created_at`,`updated_at`)
SELECT s.`id`,'expected_fee','期望费用','text','string','填写期望总价或材料单价',
       '选填。总价按整数元填写；单价可按材料填写，成交以总价为准。',
       0,NULL,'{"max_length":500}','{"fee_modes":["total","unit"],"default_fee_mode":"total","total_integer_only":true,"unit_options":["元/平","元/㎡","元/卷","元/米","元/延米","元/个","元/套","元/张","元/扇"]}',150,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM `form_steps` s
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
WHERE fs.`schema_key`='order_submit' AND s.`step_key`='product_info'
  AND NOT EXISTS (SELECT 1 FROM `form_fields` f WHERE f.`step_id`=s.`id` AND f.`field_key`='expected_fee');

UPDATE `form_fields` f
INNER JOIN `form_steps` s ON s.`id`=f.`step_id`
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
SET f.`label`='期望费用',f.`component_type`='text',f.`data_type`='string',f.`placeholder`='填写期望总价或材料单价',
    f.`help_text`='选填。总价按整数元填写；单价可按材料填写，成交以总价为准。',
    f.`is_required`=0,f.`validation_json`='{"max_length":500}',
    f.`ui_config_json`='{"fee_modes":["total","unit"],"default_fee_mode":"total","total_integer_only":true,"unit_options":["元/平","元/㎡","元/卷","元/米","元/延米","元/个","元/套","元/张","元/扇"]}',
    f.`sort_order`=150,f.`status`='active',f.`updated_at`=UTC_TIMESTAMP()
WHERE fs.`schema_key`='order_submit' AND s.`step_key`='product_info' AND f.`field_key`='expected_fee';
-- 2026-09-29：前端填写说明只保留用户决策所需信息。
-- 图片压缩、地址加密、未选类目的内部流转等实现细节仍照常执行，但不再作为用户填写提示。
UPDATE `form_fields` f
INNER JOIN `form_steps` s ON s.`id`=f.`step_id`
INNER JOIN `form_schema_versions` v ON v.`id`=s.`schema_version_id`
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
SET f.`placeholder`=CASE f.`field_key`
      WHEN 'category_ids' THEN '可多选，不确定可暂不选择'
      WHEN 'material_images' THEN '上传材料或商品图片'
      WHEN 'wall_images' THEN '上传墙面或现场照片'
      WHEN 'service_address' THEN '选择实际上门地址'
      WHEN 'expected_fee' THEN '填写期望总价或材料单价'
      ELSE f.`placeholder` END,
    f.`help_text`=CASE f.`field_key`
      WHEN 'category_ids' THEN NULL
      WHEN 'material_images' THEN '请尽量拍清材料款式和规格'
      WHEN 'wall_images' THEN '请拍清破损、发霉、楼梯或造型等情况'
      WHEN 'service_address' THEN NULL
      WHEN 'expected_fee' THEN '选填。总价按整数元填写；单价可按材料填写，成交以总价为准。'
      ELSE f.`help_text` END,
    f.`updated_at`=UTC_TIMESTAMP()
WHERE fs.`schema_key`='order_submit' AND v.`version_no`=1
  AND f.`field_key` IN ('category_ids','material_images','wall_images','service_address','expected_fee');

UPDATE `form_schemas`
SET `description`='小程序下单页配置，统一通过可视化设计器维护',`updated_at`=UTC_TIMESTAMP()
WHERE `schema_key`='order_submit';


UPDATE `order_answers`
SET `field_key_snapshot`='expected_fee',`field_label_snapshot`='期望费用'
WHERE `field_key_snapshot`='expected_price';

INSERT INTO `form_rules`
(`schema_version_id`,`rule_key`,`name`,`trigger_field_id`,`operator`,`compare_value_json`,`action_type`,`target_field_id`,`action_payload_json`,`priority`,`status`,`created_at`,`updated_at`)
SELECT v.`id`,'v240_measure_hide_expected_fee','测量时隐藏：期望费用',wf.`id`,'equals','"measurement"','hide',ef.`id`,NULL,25,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP()
FROM `form_schema_versions` v
INNER JOIN `form_schemas` fs ON fs.`id`=v.`schema_id`
INNER JOIN `form_steps` ws ON ws.`schema_version_id`=v.`id`
INNER JOIN `form_fields` wf ON wf.`step_id`=ws.`id` AND wf.`field_key`='workflow_profile'
INNER JOIN `form_steps` es ON es.`schema_version_id`=v.`id`
INNER JOIN `form_fields` ef ON ef.`step_id`=es.`id` AND ef.`field_key`='expected_fee'
WHERE fs.`schema_key`='order_submit'
  AND NOT EXISTS (SELECT 1 FROM `form_rules` r WHERE r.`schema_version_id`=v.`id` AND r.`rule_key`='v240_measure_hide_expected_fee');


-- V2.4.0 尚未正式发布：直接重建帮助中心预览结构，不兼容此前开发中的 2.4.0 草稿表。
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS `help_search_logs`;
DROP TABLE IF EXISTS `help_faq_versions`;
DROP TABLE IF EXISTS `help_faqs`;
DROP TABLE IF EXISTS `help_categories`;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE IF NOT EXISTS `help_categories` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(48) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` varchar(80) NOT NULL,
  `sort_order` int NOT NULL DEFAULT 0,
  `homepage_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_help_category_code` (`code`),
  KEY `idx_help_category_status_sort` (`status`,`sort_order`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='V2.4.0 帮助中心业务场景';

CREATE TABLE IF NOT EXISTS `help_faqs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `faq_id` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `category_id` int unsigned NOT NULL,
  `question` varchar(255) NOT NULL,
  `answer` text NOT NULL,
  `aliases` text NULL,
  `keywords` text NULL,
  `roles` varchar(120) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'all',
  `sort_order` int NOT NULL DEFAULT 0,
  `is_featured` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'draft',
  `related_faq_ids` text NULL,
  `business_entry_label` varchar(80) NOT NULL DEFAULT '',
  `business_entry_path` varchar(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT '',
  `draft_payload` longtext NULL,
  `version` int unsigned NOT NULL DEFAULT 1,
  `published_version` int unsigned NOT NULL DEFAULT 0,
  `published_at` datetime NULL,
  `created_by` int unsigned NULL,
  `updated_by` int unsigned NULL,
  `deleted_at` datetime NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_help_faq_id` (`faq_id`),
  KEY `idx_help_faq_public` (`status`,`deleted_at`,`category_id`,`sort_order`,`id`),
  KEY `idx_help_faq_updated` (`updated_at`,`id`),
  CONSTRAINT `fk_help_faq_category` FOREIGN KEY (`category_id`) REFERENCES `help_categories` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='V2.4.0 帮助中心问答';

CREATE TABLE IF NOT EXISTS `help_faq_versions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `faq_id` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version` int unsigned NOT NULL,
  `snapshot_json` longtext NOT NULL,
  `action` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `operator_admin_id` int unsigned NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_help_faq_version` (`faq_id`,`version`),
  KEY `idx_help_version_created` (`created_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='V2.4.0 帮助中心发布版本审计';

CREATE TABLE IF NOT EXISTS `help_search_logs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `query_text` varchar(120) NOT NULL DEFAULT '',
  `query_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `role_key` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'all',
  `result_count` int unsigned NOT NULL DEFAULT 0,
  `clicked_faq_id` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`), KEY `idx_help_search_zero` (`result_count`,`created_at`), KEY `idx_help_search_hash` (`query_hash`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='V2.4.0 帮助中心脱敏搜索日志';


