  MODIFY COLUMN `role` varchar(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'operator' COMMENT '角色',
  MODIFY COLUMN `status` varchar(24) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active' COMMENT '状态',
  MODIFY COLUMN `must_change_password` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '是否必须修改密码',
  MODIFY COLUMN `failed_attempts` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '登录失败次数',
  MODIFY COLUMN `locked_until` datetime DEFAULT NULL COMMENT '锁定截止时间',
  MODIFY COLUMN `last_login_at` datetime DEFAULT NULL COMMENT '最后登录时间',
  MODIFY COLUMN `last_login_ip` varchar(45) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL COMMENT '最后登录IP',
  MODIFY COLUMN `password_changed_at` datetime DEFAULT NULL COMMENT '密码修改时间',
  MODIFY COLUMN `created_at` datetime NOT NULL COMMENT '创建时间',
  MODIFY COLUMN `updated_at` datetime NOT NULL COMMENT '更新时间';
